import{_ as a,o as i,c as t,a9 as r}from"./chunks/framework.asyjyako.js";const m=JSON.parse('{"title":"Measurement model","description":"","frontmatter":{},"headers":[],"relativePath":"measurement-model.md","filePath":"measurement-model.md","lastUpdated":null}'),o={name:"measurement-model.md"};function n(s,e,l,c,p,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="Measurement-model" tabindex="-1">Measurement model <a class="header-anchor" href="#Measurement-model" aria-label="Permalink to &quot;Measurement model {#Measurement-model}&quot;">​</a></h1><p>What a metric includes, and when two records may be compared. For an introduction with plots, see <a href="./guide/understanding-measurements">Understand the result</a>.</p><p>Each metric is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>resource × lifecycle phase × execution regime × scope × method × statistic</span></span></code></pre></div><p>For example: startup, import, first execution and steady-state time are four measurements. Julia heap bytes, native heap bytes, process RSS and GPU memory are four resources.</p><h2 id="Required-context" tabindex="-1">Required context <a class="header-anchor" href="#Required-context" aria-label="Permalink to &quot;Required context {#Required-context}&quot;">​</a></h2><p>Every measurement definition states:</p><ul><li><p>metric ID, unit, collector and definition version;</p></li><li><p>phase: resolve, install, precompile, startup, import, first execution, steady state, endurance, shutdown;</p></li><li><p>regime: clean depot, cached depot, fresh process, warm process, steady state;</p></li><li><p>scope: expression, method, feature, task, process, process tree, interface, service, database, device;</p></li><li><p>clock or counter source, and whether collection is exact, repeated, sampled, static or estimated;</p></li><li><p>sample and aggregation semantics;</p></li><li><p>whether compilation, GC, child processes, GPU synchronization, loopback and protocol overhead are included;</p></li><li><p>expected perturbation and required privileges;</p></li><li><p>runtime, source, dependency, artifact, platform, hardware and environment provenance;</p></li><li><p>a semantic outcome proving both candidates did equivalent work.</p></li></ul><p>Values are comparable only when their measurement definitions and comparison keys permit it.</p><h2 id="Comparability-in-a-bundle" tabindex="-1">Comparability in a bundle <a class="header-anchor" href="#Comparability-in-a-bundle" aria-label="Permalink to &quot;Comparability in a bundle {#Comparability-in-a-bundle}&quot;">​</a></h2><p>Suite bundles retain controller thread count, hardware fingerprint, local Git revision/branch/dirty state, and SHA-256 fingerprints of the effective Project and Manifest.</p><ul><li><p>Different OS, architecture, Julia thread count or known hardware makes a comparison <code>incomparable</code>.</p></li><li><p>A changed runtime or resolved environment is a warning, because controlled campaigns may vary one deliberately.</p></li><li><p>Older bundles with missing fingerprints carry less comparability information.</p></li></ul><h2 id="Measurement-families" tabindex="-1">Measurement families <a class="header-anchor" href="#Measurement-families" aria-label="Permalink to &quot;Measurement families {#Measurement-families}&quot;">​</a></h2><ul><li><p><strong>Warm CPU execution</strong> — latency, throughput, CPU user/system, GC. BenchmarkTools, Chairmarks.</p></li><li><p><strong>Startup and import</strong> — bare startup, activation, <code>using</code>, <code>__init__</code>, extension load. Fresh processes, <code>@time_imports</code>.</p></li><li><p><strong>Compilation and TTFX</strong> — first execution, inference, codegen, recompilation, dispatch. Trace flags, SnoopCompile, JET.</p></li><li><p><strong>Precompile and images</strong> — <code>Pkg.precompile</code>, cache hit/miss, image size. PrecompileTools, PackageCompiler.</p></li><li><p><strong>Inference and invalidation</strong> — inference time, unstable returns, dispatch sites, invalidation trees. JET, SnoopCompile.</p></li><li><p><strong>CPU profiles</strong> — self/cumulative samples, task/thread, Julia and native frames. <code>Profile</code>, PProf, Speedscope.</p></li><li><p><strong>Scheduling and waiting</strong> — runnable/running/waiting tasks, locks, saturation. Wall-time profile.</p></li><li><p><strong>Julia allocation and GC</strong> — bytes/count per operation, sites, pauses. <code>Profile.Allocs</code>, <code>@allocated</code>, AllocCheck.</p></li><li><p><strong>Heap and process memory</strong> — Julia heap, retained objects, RSS/commit peak, page faults. Heap snapshots, process sampler.</p></li><li><p><strong>Microarchitecture</strong> — cycles, instructions, IPC, cache/TLB/branch misses, migrations. LinuxPerf, LIKWID.</p></li><li><p><strong>File and storage I/O</strong> — logical/physical bytes, ops, latency, warm/cold cache. App counters plus OS adapters.</p></li><li><p><strong>Network and services</strong> — payload/interface/wire bytes, packets, retries, latency. Workload counters, isolated interface.</p></li><li><p><strong>GPU/accelerator</strong> — device compile, launch, kernel, transfer, sync, VRAM. CUDA/AMDGPU, vendor profilers.</p></li><li><p><strong>Parallel/distributed</strong> — speedup, efficiency, scaling, serialization, imbalance. Thread/process matrices, MPI.</p></li><li><p><strong>Energy</strong> — joules/run, joules/op, power. RAPL/LIKWID.</p></li><li><p><strong>Domain algorithm</strong> — growth with size, time-to-solution, accuracy, iterations. Workload-declared outcomes.</p></li><li><p><strong>Load/endurance</strong> — tail latency, backpressure, errors, recovery. Isolated staged-load scenarios.</p></li></ul><p>Static analyzers emit diagnostics, not timings. A JET or AllocCheck finding can guide attribution; it is never presented as measured cost.</p><h2 id="Process-and-external-memory" tabindex="-1">Process and external memory <a class="header-anchor" href="#Process-and-external-memory" aria-label="Permalink to &quot;Process and external memory {#Process-and-external-memory}&quot;">​</a></h2><p>Set <code>:process_resources =&gt; true</code> on a feature to record a resource envelope around its backend collection.</p><ul><li><p><strong>Windows</strong> — <code>WorkingSetSize</code>, lifetime <code>PeakWorkingSetSize</code>, <code>PrivateUsage</code>.</p></li><li><p><strong>Linux</strong> — <code>VmRSS</code>, lifetime <code>VmHWM</code>, <code>smaps_rollup</code> private mappings.</p></li><li><p><strong>Other platforms</strong> — all three <code>unavailable</code>.</p></li><li><p>Unsupported fields are absent, never zero.</p></li><li><p>The envelope surrounds the whole collection, not each sample.</p></li><li><p>A process peak is never reset; <code>new_lifetime_peak</code> records only its growth during collection.</p></li><li><p>BenchmarkTools <code>memory</code>/<code>allocs</code> columns remain Julia allocation evidence, separate from process RSS.</p></li></ul><p>A feature that owns native memory can name a <code>:external_memory_probe</code> callback implementing <code>perfchecker-external-memory/1</code>. See <a href="./process-memory">Process memory</a>.</p><h2 id="Network-accounting" tabindex="-1">Network accounting <a class="header-anchor" href="#Network-accounting" aria-label="Permalink to &quot;Network accounting {#Network-accounting}&quot;">​</a></h2><p>Five scopes, weakest to strongest attribution:</p><ol><li><p><code>application</code> — payload bytes and operations the workload reports.</p></li><li><p><code>host_interface</code> — OS interface deltas; contaminated by unrelated traffic.</p></li><li><p><code>isolated_interface</code> — the same counters inside a dedicated namespace or container.</p></li><li><p><code>process_tree</code> — bytes/packets attributed by ETW/eBPF to the worker.</p></li><li><p><code>wire</code> — packet capture including transport overhead; opt-in.</p></li></ol><p>Package CI gates require level 3, 4 or a controlled interface. Latency is always labelled with its context (in-process, loopback, client end-to-end, server, DNS/TLS, scheduler wait).</p><h2 id="Native-dependency-closure" tabindex="-1">Native dependency closure <a class="header-anchor" href="#Native-dependency-closure" aria-label="Permalink to &quot;Native dependency closure {#Native-dependency-closure}&quot;">​</a></h2><p>Four layers:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>declared package → resolved artifact → loaded native image → spawned process / service</span></span></code></pre></div><p><code>dependency_evidence()</code> snapshots the first layer&#39;s current process. <code>ProbeSpec</code> adds a feature-owned functional check inside the prepared worker. Successful resolution alone never proves an ABI or symbol is usable. Julia allocation counters never claim to cover native allocators.</p><h2 id="Julia-runtimes" tabindex="-1">Julia runtimes <a class="header-anchor" href="#Julia-runtimes" aria-label="Permalink to &quot;Julia runtimes {#Julia-runtimes}&quot;">​</a></h2><p><code>JuliaRuntimeSpec</code> adds a runtime axis separate from package versions.</p><ul><li><p>Moving selectors (<code>release</code>, <code>rc</code>, <code>nightly</code>) are probed in a fresh process; the exact version, commit, bindir and LLVM version are frozen before workers start.</p></li><li><p><code>run_julia_runtime_campaign</code> compares bundles without treating a runtime difference as an automatic incompatibility.</p></li><li><p>Failures are phase-classified: resolver vs precompile vs runtime crash vs suite failure vs launch vs missing report.</p></li></ul><p>Two campaign styles:</p><ul><li><p><strong>Strict runtime attribution</strong> keeps source, dependencies, workload and machine fixed while Julia changes.</p></li><li><p><strong>Realistic compatibility</strong> resolves independently under each runtime and reports dependency differences without attributing them to Julia.</p></li></ul><p><a id="Required-measurement-context"></a><a id="Julia-performance-families"></a><a id="Package-archetypes"></a><a id="Julia-stable-versus-candidate-runtimes"></a></p>',33)])])}const h=a(o,[["render",n]]);export{m as __pageData,h as default};
